-- CLASS_INTEGRATION_STRICT: class:druid
-- PRESENTATION ONLY. Replaces Druid authorExplanation / author_description.
-- Exact rules, resources, actions, rolls, choices, comments and spell catalog are untouched.

begin;

create or replace function private.druid_voss_in_world_explanation(
  p_catalog_key text,
  p_level integer,
  p_label text
)
returns text
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_catalog text := lower(coalesce(p_catalog_key, ''));
  v_label text := coalesce(p_label, '');
begin
  if v_catalog = 'class:druid' then
    case p_level::text || ':' || v_label
      when '1:Заклинания' then return 'Друид не приказывает природе. Он скорее знает, куда ткнуть палкой, чтобы она сама решила, что сегодня уместнее: затянуть рану, поднять корни или ударить кого-нибудь молнией. Я видел людей, которые называли это гармонией. Обычно они говорили так до первой грозы.';
      when '1:Друидический' then return 'У друидов есть язык для разговоров, которые они предпочитают не вести при остальных. Иногда послание выглядит как царапина на коре, иногда собеседником оказывается белка. Если белка знает о засаде больше разведчика, я бы сначала уволил разведчика, а потом уже задавал вопросы белке.';
      when '1:Первобытный путь' then return 'Рано или поздно каждый друид решает, кем ему удобнее переживать неприятности: тем, кто лучше понимает древние силы, или тем, кто умеет встретить неприятность в броне. Второй вариант мне всегда казался честнее. Железо хотя бы не притворяется мудрым.';
      when '2:Дикая форма' then return 'Есть люди, которые приспосабливаются к опасности. Друид считает это полумерой и меняет тело целиком. Самое неприятное — внутри волка, медведя или гигантской ящерицы всё ещё сидит тот же человек и прекрасно помнит, кто пять минут назад назвал его смешным.';
      when '2:Ограничения Дикой формы' then return 'Природа не вручает молодому друиду крылья в первый день. Сначала пусть научится не потеряться в четырёх лапах и не утонуть в первой же реке. К тем, кто пережил этот этап, лес со временем становится заметно щедрее.';
      when '2:Дикий спутник' then return 'Умный путешественник не суёт голову в каждую тёмную щель лично. Друид в этом вопросе неожиданно разумен: может отправить вперёд маленького зверя и посмотреть, что именно его съест. Разведка становится гораздо приятнее, когда первым умирает не разведчик.';
      when '3:Круг друида' then return 'Друиды любят говорить, что все они служат одной природе. Потом собираются в Круги и начинают спорить, что важнее: луна, море, грибы, звёзды или хороший пожар. Для меня это всё те же люди из леса, просто теперь заранее известно, какую именно беду ждать.';
      when '4:Улучшение характеристик' then return 'К этому времени друид обычно понимает, что одних разговоров с деревьями мало и полезно чему-нибудь научиться самому. Редкий здоровый этап развития. Ни рогов, ни спор, ни внезапного превращения в барсука.';
      when '5:Дикое возрождение' then return 'Иногда зверя из друида выбивают силой, иногда магию выжимают досуха. Нормальный человек после этого ложится и жалуется. Друид начинает рыться внутри себя и почти всегда находит ещё что-нибудь, чем можно продолжить драку. Упрямство у них, похоже, тоже природный ресурс.';
      when '7:Стихийная ярость' then return 'В какой-то момент друиду перестаёт хватать просто огня, холода и зубов по отдельности. Один начинает вкладывать бурю в слова, другой — в удар. Итог одинаковый: рядом становится громче, ярче и заметно меньше желающих спорить о бережном отношении к природе.';
      when '8:Улучшение характеристик' then return 'После нескольких лет среди хищников, духов и людей, которые хуже хищников, даже друид начинает ценить обычную выучку. Хороший навык не требует полной луны и не пытается сожрать сапог, пока вы спите.';
      when '12:Улучшение характеристик' then return 'Опытный друид уже редко учится ради красоты. Обычно он вспоминает последнюю драку, последнюю ошибку и того, кого после неё пришлось хоронить. Очень убедительная учебная программа, хотя преподаватели в ней долго не задерживаются.';
      when '15:Улучшенная стихийная ярость' then return 'То, что раньше было дурной привычкой, к этому времени становится ремеслом. Если друид годами вплетал стихию в бой, она начинает слушаться его почти так же охотно, как голодный волк слушает звук открывающейся клетки.';
      when '16:Улучшение характеристик' then return 'Дожившие сюда уже не становятся лучше случайно. Они точат себя так же, как воин точит клинок: медленно, привычно и с очень ясной памятью о том, что случается с тупым инструментом в плохих руках.';
      when '18:Заклинания зверя' then return 'Я долго утешал себя мыслью, что медведь хотя бы не умеет колдовать. Оказалось, это было временное преимущество. Если зверь перед вами вдруг начинает слишком осмысленно рычать, не ждите конца фразы.';
      when '19:Эпический дар' then return 'На этом пути наступает момент, когда слово «талант» звучит слишком скромно. Друид пережил столько вещей, которые должны были его убить, что мир словно начинает уступать ему дорогу. Я бы тоже уступил. Мир иногда удивительно здравомыслящ.';
      when '20:Архидруид' then return 'Старый архидруид — уже не человек, который живёт рядом с природой. Это часть местности, просто иногда она разговаривает, ходит и смотрит на вас так, будто помнит деревья, выросшие на месте вашей будущей могилы. С такими я не спорю. У них слишком много времени доказать свою правоту.';
      else return null;
    end case;
  end if;

  if v_catalog = 'subclass:druid:circle-of-dreams' then
    case v_label
      when 'Бальзам Летнего Двора' then return 'Фейская милость выглядит слишком красиво для поля боя: тёплый свет, запах лета — и человек, которого уже мысленно записали в покойники, снова ругается. Я предпочитаю бинты. Но если раненый снова ругается, спорить с методом поздно.';
      when 'Очаг лунного света и тени' then return 'Хороший лагерь — тот, который враг не нашёл. Друид Снов умеет устроить ночь так, будто ваша компания просто выпала из чужого внимания. Костёр горит, люди отдыхают, а снаружи остаётся только очень неудачное место для засады.';
      when 'Скрытые пути' then return 'Феи никогда не ходят туда же, куда остальные. Друид учится у них этой мерзкой привычке и исчезает с дороги ровно тогда, когда враг уже уверен, что загнал его в угол. Угол после этого чувствует себя особенно глупо.';
      when 'Странник во снах' then return 'Для большинства сон — место, где тело наконец перестаёт принимать плохие решения. Для этого друида сон становится дорогой, окном и иногда запасным выходом. Я бы не хотел жить в мире, где человек может уйти из лагеря, просто слишком правильно заснув. К сожалению, мы в нём живём.';
    end case;
  elsif v_catalog = 'subclass:druid:circle-of-spores' then
    case v_label
      when 'Ореол спор и Симбиотическая сущность' then return 'Обычно грибок на человеке означает, что лекаря позвали слишком поздно. Здесь грибок — союзник. Он висит вокруг друида невидимой угрозой, а когда хозяин впускает его глубже, становится ясно: лечить надо уже тех, кто подошёл слишком близко.';
      when 'Грибковое заражение' then return 'Я видел мёртвых, которые вставали из-за некромантов, проклятий и плохих похорон. Эти встают потому, что грибы ещё не закончили пользоваться телом. Есть в этом что-то почти деловое, если не смотреть на лицо покойника.';
      when 'Распространение спор' then return 'Раньше опасным был сам друид. Теперь он может оставить кусок своей грибной неприятности отдельно и заставить поле боя медленно превращаться в подвал, который никто не проветривал лет двадцать. Не стойте в красивом облачке. Вообще никогда.';
      when 'Грибковое тело' then return 'Со временем грибы перестают быть жильцами и становятся частью хозяина. После этого многие вещи, которые ломают обычного человека, встречают внутри друида очень странный коллективный отказ умирать. Медики такое не любят. Могильщики тоже.';
    end case;
  elsif v_catalog = 'subclass:druid:circle-of-the-shepherd' then
    case v_label
      when 'Речь леса и Духовный тотем' then return 'Пастырь понимает зверей достаточно хорошо, чтобы перестать считать их молчаливыми. А когда начинается драка, рядом с ним встаёт дух того, что группе сейчас нужнее. Я уважаю любой план, в котором огромный призрачный медведь считается частью подготовки.';
      when 'Могучий призыватель' then return 'Когда обычный друид зовёт зверя, приходит зверь. Когда зовёт Пастырь, тот приходит так, будто заранее поел, разозлился и знает, кого кусать. Очень полезное различие, особенно если стоите с правильной стороны клыков.';
      when 'Дух-хранитель' then return 'Стая рядом с Пастырем дерётся дольше, чем должна по всем разумным признакам. Дух держит их на ногах, а они продолжают делать то, для чего были позваны. Хорошая организация. Людям бы иногда не помешало посмотреть и поучиться у волков.';
      when 'Верный призыв' then return 'Самое убедительное доказательство хорошего пастуха — стадо приходит, когда он уже не может позвать. Если друид падает, лес словно замечает это сам и присылает тех, у кого зубов больше, чем терпения. Трогательно. Для нас. Не для противника.';
    end case;
  elsif v_catalog = 'subclass:druid:circle-of-wildfire' then
    case v_label
      when 'Заклинания Круга и Огненный дух' then return 'Этот друид приходит не с питомцем, а с пожаром, который научился слушаться. Он летает рядом, плюётся пламенем и уносит людей из беды так, будто спасение и поджог — две стороны одного ремесла. Наверное, для леса так и есть.';
      when 'Усиленная связь' then return 'Через какое-то время огненный дух перестаёт быть спутником и становится второй рукой друида. Пламя проходит через него, лечение приходит оттуда, откуда секунду назад ждали ожога. Никогда не доверяйте огню только потому, что сегодня он полезный.';
      when 'Прижигающее пламя' then return 'После смерти рядом остаётся огонь. Один человек шагнёт в него и выйдет живее, другой — наоборот. Очень по-друидски: даже труп на земле превращается в вопрос, на который лучше знать ответ заранее.';
      when 'Пылающее возрождение' then return 'Огненный дух привязывается к хозяину сильнее, чем я ожидал от существа, состоящего из пожара. Когда друид уже должен лежать и не вставать, дух может сгореть до конца и вытолкнуть его обратно к жизни. После такого я бы хотя бы перестал называть его питомцем.';
    end case;
  elsif v_catalog = 'subclass:druid:land' then
    case v_label
      when 'Заклинания Круга Земли' then return 'Земля везде говорит по-разному. Пустыня учит одному, мороз — другому, лес и болото вообще дают советы, которые лучше не повторять за ужином. Друид Земли просыпается и слушает, какой голос сегодня ему нужнее.';
      when 'Помощь земли' then return 'Хорошая почва умеет одновременно кормить одно и забирать другое. Этот друид просто ускоряет процесс до скорости, удобной для драки. Один рядом выпрямляется, другой внезапно понимает, почему кладбища тоже считают частью природы.';
      when 'Природное восстановление' then return 'Есть маги, которым нужен кабинет, книга и тишина. Друид Земли может просто посидеть на земле так, будто разговаривает со старым товарищем, и встать заметно опаснее, чем сел. Если увидите такое на привале, не мешайте. Пусть лучше земля отвечает ему, чем вам.';
      when 'Защита природы' then return 'Чем дольше друид живёт голосом выбранной земли, тем меньше эта земля способна его удивить. Жара, мороз, яд или гроза встречают в нём не гостя, а почти местного. Природа своих тоже убивает, конечно. Просто обычно чуть менее охотно.';
      when 'Святилище природы' then return 'Когда укрытия нет, друид приводит укрытие с собой. Деревья и лозы встают там, где секунду назад была голая земля, а потом ещё и идут вслед за группой. Я много раз просил разведчиков найти передвижной лес. Ни один не вернулся с хорошим объяснением.';
    end case;
  elsif v_catalog = 'subclass:druid:moon' then
    case v_label
      when 'Формы круга и заклинания Луны' then return 'Обычный друид носит зверя как запасное тело. Лунный — как любимый доспех. Он входит в шкуру хищника без той неловкости, с какой остальные впервые пытаются понять, куда девать хвост. Если зверь двигается слишком по-человечески уверенно, бегите раньше, чем узнаете почему.';
      when 'Улучшенные формы круга' then return 'Со временем зверь под луной перестаёт быть просто зверем. В клыках появляется холодный свет, в движениях — та упрямая собранность, которой животному знать не положено. Самая плохая разновидность медведя — та, что ещё и понимает, зачем пришла.';
      when 'Лунный шаг' then return 'Большого хищника хотя бы обычно слышно. Лунный друид считает это недостатком и учится пропадать с одного места, чтобы возникнуть в другом уже на расстоянии укуса. После первого такого случая я перестал считать стену за спиной достаточной мерой безопасности.';
      when 'Лунная форма' then return 'Когда луна окончательно входит в привычки этого Круга, зверь начинает выглядеть как дурная легенда, которую кто-то зачем-то сделал настоящей. Он появляется там, где его не было, и бьёт так, будто вместе с лапой падает кусок ночного неба. Красиво. Очень неудобно умирать от красивого.';
      when 'Лунный шаг · спутник' then return 'Хуже телепортирующегося медведя только телепортирующийся медведь, который прихватил товарища. Лунный друид со временем понимает, что короткая дорога полезнее, если можно утащить по ней ещё одного человека. Обычно того, кто согласился заранее. Обычно.';
    end case;
  elsif v_catalog = 'subclass:druid:sea' then
    case v_label
      when 'Гнев моря и заклинания Круга' then return 'Море не обязано быть рядом, чтобы испортить вам день. Друид этого Круга носит шторм с собой: воздух сыреет, ветер злится, и кто-то рядом внезапно вспоминает, как неприятно тонуть даже на суше. Очень морская философия.';
      when 'Связь с водой' then return 'Сначала друид учится жить со штормом. Потом вода вообще перестаёт считать его сухопутным гостем. Он движется в ней так, будто родился по другую сторону берега, а буря вокруг него становится шире. Рыбам остаётся только привыкнуть к новому соседу.';
      when 'Рождённый бурей' then return 'В какой-то момент шторм признаёт друида своим. Холод, гром и молния перестают звучать для него как предупреждение, а земля — как обязательное место для ног. Когда человек начинает лететь внутри собственной непогоды, вопрос «где корабль?» уже не главный.';
      when 'Дар океана' then return 'Самое тревожное в личном шторме — возможность одолжить его другу. Один друид уже портит погоду. Два центра бури на поле боя — это момент, когда хороший капитан молча разворачивает корабль, даже если корабля рядом нет.';
    end case;
  elsif v_catalog = 'subclass:druid:stars' then
    case v_label
      when 'Звёздная карта' then return 'Звёздный друид носит кусок ночного неба как другие носят карту дорог. Разница в том, что его карта иногда отвечает. Если созвездия начинают помогать вам в драке, поблагодарите после боя. Во время боя не отвлекайте небо.';
      when 'Звёздная форма' then return 'Он не превращается в зверя — он позволяет ночному небу проступить сквозь собственное тело. В один вечер созвездие делает его охотником, в другой — целителем, в третий — существом, которое невозможно выбить из мысли обычным ударом. Я предпочитаю людей, у которых внутри просто органы.';
      when 'Космическое знамение' then return 'Иногда утром друид смотрит на звёзды и весь день знает: сегодня небо будет кому-то помогать, а кому-то ставить подножки. Не спрашивайте, как оно выбирает сторону. Если бы судьба объяснялась, гадатели давно остались бы без работы.';
      when 'Мерцающие созвездия' then return 'Опытный звёздный друид перестаёт носить одно созвездие как татуировку и начинает менять небо на себе прямо по ходу дела. Только привыкли к лучнику — уже видите дракона. Врагу остаётся надеяться, что следующим будет что-нибудь без зубов.';
      when 'Звёздная форма · усиление' then return 'Ночное небо постепенно занимает в нём всё больше места. Свет становится ярче, созвездия — увереннее, а привычные ограничения тела начинают выглядеть как предложения, а не законы. Никогда не радуйтесь, когда магия начинает считать законы предложениями.';
      when 'Полон звёзд' then return 'К этому времени клинок попадает уже не совсем в человека. Часть удара будто уходит в холодный свет между звёздами, где железу совершенно нечего делать. Хорошая защита. Плохой повод задуматься, сколько человека там вообще осталось.';
    end case;
  end if;

  return null;
end;
$$;

create or replace function private.druid_voss_template_explanation(p_catalog_key text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case p_catalog_key
    when 'class:druid' then 'Я ходил с друидами достаточно, чтобы перестать называть их просто магами. Магу нужен ответ из книги; друид сначала смотрит на небо, грязь, следы зверя, потом может сам стать зверем и проверить всё лично. Полезные люди. Просто никогда не забывайте, что у вашего проводника может оказаться запасной комплект зубов.'
    when 'subclass:druid:circle-of-dreams' then 'Круг Снов связался с феями и каким-то чудом вынес из этого не проклятие, а полезные привычки. Они умеют вытаскивать людей из плохих мест, прятать ночлег и находить дороги там, где обычный путник видит только сон. Всё равно пересчитайте пальцы после пробуждения.'
    when 'subclass:druid:land' then 'Эти друиды слушают землю так, как старый следопыт слушает лес перед засадой. Пустыня, тундра, болото или роща для них не фон, а собеседник со своим характером. Мне это нравится больше разговоров со звёздами: земля хотя бы находится под ногами.'
    when 'subclass:druid:moon' then 'Круг Луны решил, что человеческий облик — досадная пауза между нормальными состояниями. Они превращаются так уверенно, будто родились с клыками, а потом ещё удивляются, почему в таверне им не разрешают спать у двери. Я бы тоже не разрешил. Дверь одна.'
    when 'subclass:druid:sea' then 'Некоторые моряки носят с собой запах соли. Друид Моря приносит само море — с ветром, холодом и характером человека, которому только что сказали, что корабль уже ушёл. Если вокруг одного пассажира начинает портиться погода, пересаживайтесь.'
    when 'subclass:druid:circle-of-the-shepherd' then 'Пастырь никогда не приходит один, даже если рядом никого не видно. За ним стоят звери, духи и вся та лесная компания, которая обычно наблюдает из кустов. Хороший Пастырь похож на командира. Плохой — на причину, по которой весь лес внезапно бежит в вашу сторону.'
    when 'subclass:druid:circle-of-spores' then 'Круг Спор смотрит на труп и видит не конец, а свободное место для новой работы. Грибы у них живут на коже, в воздухе и, судя по привычкам, где-то между здравым смыслом и любопытством. Зато они честны: в конце концов съедят всех, без любимчиков.'
    when 'subclass:druid:stars' then 'Звёздные друиды слишком долго смотрели в ночное небо и дождались, пока оно посмотрело в ответ. Они носят созвездия как другие носят оружие: одно помогает бить, другое спасать, третье просто не даёт им развалиться в самый неудобный момент. Красиво. От этого мне только тревожнее.'
    when 'subclass:druid:circle-of-wildfire' then 'Лесной пожар у обычного человека означает бежать. У этого Круга — позвать приятеля. Их огонь умеет уничтожать, спасать и освобождать место для нового, что звучит почти мудро, пока не понимаешь, что мудрость сейчас стоит рядом и горит.'
    else null
  end;
$$;

update public.rule_templates rt
set author_description = coalesce(private.druid_voss_template_explanation(rt.catalog_key), rt.author_description),
    updated_at = now()
where rt.is_active
  and (rt.catalog_key = 'class:druid' or rt.catalog_key like 'subclass:druid:%');

update public.rule_template_levels rtl
set mechanics = coalesce((
  select jsonb_agg(
    case
      when m->>'type' = 'grant' and m->>'target' = 'feature'
      then case
        when private.druid_voss_in_world_explanation(rt.catalog_key, rtl.level, m->'payload'->>'label') is not null
        then jsonb_set(
          m,
          '{payload,authorExplanation}',
          to_jsonb(private.druid_voss_in_world_explanation(rt.catalog_key, rtl.level, m->'payload'->>'label')),
          true
        )
        else m
      end
      else m
    end
    order by ord
  )
  from jsonb_array_elements(coalesce(rtl.mechanics, '[]'::jsonb)) with ordinality q(m, ord)
), '[]'::jsonb)
from public.rule_templates rt
where rt.id = rtl.template_id
  and rt.is_active
  and (rt.catalog_key = 'class:druid' or rt.catalog_key like 'subclass:druid:%');

-- Guard only the narration cards authored by this pass. Older unrelated Druid
-- presentation rows may still exist, but they are outside this targeted rewrite.
do $$
declare v_bad integer;
begin
  with authored as (
    select private.druid_voss_in_world_explanation(rt.catalog_key, rtl.level, m->'payload'->>'label') as text
    from public.rule_templates rt
    join public.rule_template_levels rtl on rtl.template_id = rt.id
    cross join lateral jsonb_array_elements(coalesce(rtl.mechanics, '[]'::jsonb)) m
    where rt.is_active
      and (rt.catalog_key = 'class:druid' or rt.catalog_key like 'subclass:druid:%')
      and m->>'type' = 'grant'
      and m->>'target' = 'feature'
      and private.druid_voss_in_world_explanation(rt.catalog_key, rtl.level, m->'payload'->>'label') is not null
  )
  select count(*) into v_bad
  from authored
  where text ~* '(\b[0-9]+к[0-9]+\b|\bСл\b|\bCR\b|\bHP\b|ячейк|модификатор|бонусным действием|магическим действием|реакцией|использовани[ея]|\bфут(ов|а)?\b)';

  if v_bad > 0 then
    raise exception 'Druid Voss narration leaked tabletop mechanics into % authored explanations', v_bad;
  end if;
end;
$$;

drop function private.druid_voss_in_world_explanation(text, integer, text);
drop function private.druid_voss_template_explanation(text);

commit;
